import{_ as a,c as r,o as t,b0 as n}from"./chunks/framework.Dmsv_Tiv.js";const s="/media-docs/assets/image-20240529073721504.BMrUbuEq.png",i="/media-docs/assets/image-20240529073731737.D_hEGLZP.png",m=JSON.parse('{"title":"LV015-三原色","description":null,"frontmatter":{"title":"LV015-三原色","date":"2025-09-18T16:30:42.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/color/126b08c8926212fa65fef187","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-09-18T16:30:42.303Z","fulluuid":"a65fef1875514074b6c553c29ed97022","useduuid":"a65fef187"}},"headers":[],"relativePath":"sdoc/image/color/126b08c8926212fa65fef187.md","filePath":"sdoc/01-图像/10-色彩基础/LV015-三原色.md","lastUpdated":1767537778000}'),l={name:"sdoc/image/color/126b08c8926212fa65fef187.md"};function h(o,e,w,p,d,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="lv015-三原色" tabindex="-1">LV015-三原色 <a class="header-anchor" href="#lv015-三原色" aria-label="Permalink to &quot;LV015-三原色&quot;">​</a></h1><p>原色以不同比例混合时，会产生其他颜色。在不同的色彩空间系统中，有不同的原色组合。可以分为“叠加型”和“消减型”两种系统。所以三原色就可以分为印刷的三原色和光的三原色两种。</p><h2 id="一、印刷的三原色" tabindex="-1">一、印刷的三原色 <a class="header-anchor" href="#一、印刷的三原色" aria-label="Permalink to &quot;一、印刷的三原色&quot;">​</a></h2><p><strong>印刷的三原色</strong>： 青（Cyan）、品红（Magenta）、黄（Yellow） (CMYK)</p><p>消减型原色又称为减色原色。一般来说以反射光源或<a href="https://www.wikiwand.com/zh-hans/%E9%A2%9C%E6%96%99" target="_blank" rel="noreferrer">颜料</a>著色时所使用的色彩是属于“消减型”的原色系统，此系统中包含了<a href="https://www.wikiwand.com/zh-hans/%E9%9D%92%E8%89%B2" target="_blank" rel="noreferrer">青色</a>（<strong>Cyan</strong>）、紫色或<a href="https://www.wikiwand.com/zh-hans/%E6%B4%8B%E7%B4%85%E8%89%B2" target="_blank" rel="noreferrer">品红色</a>（<strong>Magenta</strong>）、<a href="https://www.wikiwand.com/zh-hans/%E9%BB%83%E8%89%B2" target="_blank" rel="noreferrer">黄色</a>(<strong>Yellow</strong>)三种原色<a href="https://www.wikiwand.com/zh-hans/%E5%8E%9F%E8%89%B2#cite_note-4" target="_blank" rel="noreferrer">[4]</a>，是另一套“三原色”系统。在传统的<a href="https://www.wikiwand.com/zh-hans/%E9%A2%9C%E6%96%99" target="_blank" rel="noreferrer">颜料</a>著色技术上，通常<a href="https://www.wikiwand.com/zh-hans/%E7%B4%85" target="_blank" rel="noreferrer">红</a>、<a href="https://www.wikiwand.com/zh-hans/%E9%BB%83" target="_blank" rel="noreferrer">黄</a>、<a href="https://www.wikiwand.com/zh-hans/%E8%97%8D" target="_blank" rel="noreferrer">蓝</a>会被视为原色颜料，这种系统较受艺术家的欢迎<a href="https://www.wikiwand.com/zh-hans/%E5%8E%9F%E8%89%B2#cite_note-5" target="_blank" rel="noreferrer">[5]</a>。（现代的美术书已不采用这种说法，而采用消减型的三原色。）当这三种原色混合时可以产生其他颜色，例如黄色与青色混合可以产生<a href="https://www.wikiwand.com/zh-hans/%E7%B6%A0" target="_blank" rel="noreferrer">绿</a>色，黄色与品红色混合可以产生红色，品红色与<a href="https://www.wikiwand.com/zh-hans/%E9%9D%92%E8%89%B2" target="_blank" rel="noreferrer">青色</a>混合可以产生蓝色。当这三种原色以等比例叠加在一起时，会变成<a href="https://www.wikiwand.com/zh-hans/%E7%81%B0" target="_blank" rel="noreferrer">灰</a>色；若将此三原色的<a href="https://www.wikiwand.com/zh-hans/%E8%89%B2%E5%BA%A6_(%E8%89%B2%E5%BD%A9%E5%AD%A6)" target="_blank" rel="noreferrer">饱和度</a>均调至最大并且等量混合时，理论上会呈现<a href="https://www.wikiwand.com/zh-hans/%E9%BB%91%E8%89%B2" target="_blank" rel="noreferrer">黑色</a>，但实际上由于颜料的原因呈现的是浊褐色。</p><p>正因如此，在<a href="https://www.wikiwand.com/zh-hans/%E5%8D%B0%E5%88%B7" target="_blank" rel="noreferrer">印刷</a>技术上，人们采用了第四种“原色”——<a href="https://www.wikiwand.com/zh-hans/%E9%BB%91%E8%89%B2" target="_blank" rel="noreferrer">黑色</a>，以弥补三原色之不足。这套原色系统常被称为“<strong>CMYK色彩空间</strong>”，亦即由青（C）品红（M）黄（Y）以及黑（K）所组合出的色彩系统。</p><img src="'+s+'" alt="image-20240529073721504" style="zoom:80%;"><p>印刷色是光照射在印刷物上， 然后折射到人眼的光的合成，所以印刷色会比光学暗淡，因为印刷色是经过印刷物过滤过光合成的，自然会比较相对暗淡。</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C(100) + M(100) + Y(100) = 黑色(100,100,100)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>可见黑色就是青色、品与黄色之和，但是这三种颜色混成的黑色不够纯，所以印刷学就引进了K(Black)黑色，因为B已经被Blue占用，所以黑色就只好用引文字母黑色的最后一个字母K，所以：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">C(100) + M(100) + Y(100) + K(100) 等价于 C(0) + M(0) + Y(0) + K(100) = 黑色</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="二、光的三原色" tabindex="-1">二、光的三原色 <a class="header-anchor" href="#二、光的三原色" aria-label="Permalink to &quot;二、光的三原色&quot;">​</a></h2><p><strong>光的三原色</strong>： 红（Red)、绿（Green）、蓝（Blue) （RGB）。</p><p>一般来说以光源投射时所使用的色彩是属于“叠加型”的原色系统，此系统中包含了<a href="https://www.wikiwand.com/zh-hans/%E7%B4%85" target="_blank" rel="noreferrer">红</a>、<a href="https://www.wikiwand.com/zh-hans/%E7%B6%A0" target="_blank" rel="noreferrer">绿</a>、<a href="https://www.wikiwand.com/zh-hans/%E8%97%8D" target="_blank" rel="noreferrer">蓝</a>三种原色，亦称为“三原色”。使用这三种原色可以产生其他颜色，例如红色与绿色混合可以产生<a href="https://www.wikiwand.com/zh-hans/%E9%BB%83%E8%89%B2" target="_blank" rel="noreferrer">黄色</a>或<a href="https://www.wikiwand.com/zh-hans/%E6%A9%99%E8%89%B2" target="_blank" rel="noreferrer">橙色</a>，绿色与蓝色混合可以产生<a href="https://www.wikiwand.com/zh-hans/%E9%9D%92%E8%89%B2" target="_blank" rel="noreferrer">青色</a>（<strong>Cyan</strong>），蓝色与红色混合可以产生紫色或<a href="https://www.wikiwand.com/zh-hans/%E6%B4%8B%E7%B4%85%E8%89%B2" target="_blank" rel="noreferrer">品红色</a>（<strong>Magenta</strong>）。当这三种原色以等比例叠加在一起时，会变成<a href="https://www.wikiwand.com/zh-hans/%E7%81%B0" target="_blank" rel="noreferrer">灰</a>色；若将此三原色的<a href="https://www.wikiwand.com/zh-hans/%E4%BA%AE%E5%BA%A6" target="_blank" rel="noreferrer">强度</a>均调至最大并且等量重叠时，则会呈现<a href="https://www.wikiwand.com/zh-hans/%E7%99%BD" target="_blank" rel="noreferrer">白</a>色。</p><p>这套原色系统常被称为“<strong>RGB色彩空间</strong>”，亦即由红（R）绿（G）蓝（B）所组合出的色彩系统。</p><img src="'+i+'" alt="image-20240529073731737" style="zoom:80%;"><p>光学三原色如何得到黑色？ 配色如下：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">R(0) + G(0) + B(0) + A(255) = C(0) + M(0) + Y(0) + K(100) = 黑色</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',18)])])}const f=a(l,[["render",h]]);export{m as __pageData,f as default};
